"use client";

import { useEffect, useRef, useState, useSyncExternalStore, type FormEvent } from "react";
import { Activity, ArrowDownToLine, ArrowRight, ArrowUpRight, Bell, Brain, Check, ChevronRight, Clock3, FileText, FolderOpen, Heart, History, Home, Inbox, Link2, LockKeyhole, LogOut, MessageCircle, Moon, MoreHorizontal, Pencil, Plus, Radar, RefreshCw, Send, Settings, ShieldCheck, Sparkles, Sun, Trash2, Upload, Wallet, X } from "lucide-react";
import { lifeToday, reminderDisplayOccurrence, summarizeFinances, type LifeCollection, type LifeCommand, type LifeMemory, type LifeState, type LifeTask } from "@/lib/life/domain";
import { Empty, Field, Metric, Modal, Panel, Progress, TextButton, dayLabel, eur, formString } from "./ui";
import { RecordEditor, type EditorRequest } from "./record-editor";
import { Finance, maybeEur } from "./finance";
import { Health } from "./health";

export type LifeCapabilities = { ai: boolean; aiModel: string; aiReasoning: string; push: boolean };
export type LifeAppProps = { initialState: LifeState; initialVersion: number; capabilities: LifeCapabilities; initialSession?: unknown };
type View = "today" | "finance" | "health" | "projects" | "assistant" | "memory" | "reminders" | "documents" | "radar" | "settings";
type Proposal = { id: string; label: string; command: LifeCommand };
type ImportPreview = { document?: unknown; proposals: Proposal[]; notes?: string[]; duplicate?: boolean; version: number; complete?: boolean };
const navigation = [
  { id: "today", title: "Dnes", icon: Home }, { id: "finance", title: "Financie", icon: Wallet }, { id: "health", title: "Zdravie", icon: Heart },
  { id: "projects", title: "Projekty a ciele", icon: FolderOpen }, { id: "assistant", title: "Asistent", icon: Sparkles }, { id: "memory", title: "Pamäť a pravidlá", icon: Brain },
  { id: "reminders", title: "Pripomienky", icon: Bell }, { id: "documents", title: "Podklady a nápady", icon: Inbox }, { id: "radar", title: "Radar", icon: Radar }, { id: "settings", title: "Nastavenia", icon: Settings },
] as const;
const scopeLabels = { general: "Všeobecné", finance: "Financie", health: "Zdravie", projects: "Projekty" };
let fallbackTheme: "light" | "dark" = "dark";
function readTheme(): "light" | "dark" { try { return window.localStorage.getItem("si-for-me-theme") === "light" ? "light" : "dark"; } catch { return fallbackTheme; } }
function subscribeTheme(callback: () => void) { window.addEventListener("storage", callback); window.addEventListener("si-for-me-theme", callback); return () => { window.removeEventListener("storage", callback); window.removeEventListener("si-for-me-theme", callback); }; }
function storeTheme(theme: "light" | "dark") { fallbackTheme = theme; try { window.localStorage.setItem("si-for-me-theme", theme); } catch { /* Theme still works when browser storage is unavailable. */ } window.dispatchEvent(new Event("si-for-me-theme")); }


async function readResponse(response: Response) {
  let body: Record<string, unknown>;
  try { body = await response.json(); } catch { throw new Error("Server neposlal čitateľnú odpoveď. Skús obnoviť prehľad."); }
  if (!response.ok) throw Object.assign(new Error(typeof body.error === "string" ? body.error : "Zmenu sa nepodarilo uložiť."), { status: response.status });
  return body;
}

export function LifeApp({ initialState, initialVersion, capabilities: initialCapabilities }: LifeAppProps) {
  const [state, setState] = useState(initialState);
  const theme = useSyncExternalStore(subscribeTheme, readTheme, () => "dark" as const);
  const messagesRef = useRef<HTMLDivElement>(null);
  const [version, setVersion] = useState(initialVersion);
  const versionRef = useRef(initialVersion);
  const lockRef = useRef(false);
  const [capabilities, setCapabilities] = useState(initialCapabilities);
  const [view, setView] = useState<View>("today");
  const [mobileMenu, setMobileMenu] = useState(false);
  const [busy, setBusy] = useState(false);
  const [notice, setNotice] = useState<{ kind: "error" | "success"; message: string } | null>(null);
  const [editor, setEditor] = useState<EditorRequest | null>(null);
  const editorVersion = useRef(initialVersion);
  const [memoryHistory, setMemoryHistory] = useState<LifeMemory | null>(null);
  const [deletion, setDeletion] = useState<{ collection: LifeCollection; id: string; title: string } | null>(null);
  const [importOpen, setImportOpen] = useState(false);
  const [importPreview, setImportPreview] = useState<ImportPreview | null>(null);
  const [importBusy, setImportBusy] = useState(false);
  const [importError, setImportError] = useState("");
  const [chatValue, setChatValue] = useState("");
  const [chatBusy, setChatBusy] = useState(false);
  const [chatProposals, setChatProposals] = useState<Proposal[]>([]);
  const [proposalVersion, setProposalVersion] = useState<number | null>(null);
  const lastMessageId = state.chatMessages.at(-1)?.id;
  useEffect(() => { if (view === "assistant" && messagesRef.current) messagesRef.current.scrollTop = messagesRef.current.scrollHeight; }, [lastMessageId, chatBusy, view]);
  const today = lifeToday(state.settings.timezone);
  const visibleName = state.settings.displayName;
  const accept = (body: Record<string, unknown>) => {
    if (body.state) setState(body.state as LifeState);
    if (typeof body.version === "number") { setVersion(body.version); versionRef.current = body.version; }
    if (body.capabilities) setCapabilities(body.capabilities as LifeCapabilities);
  };
  async function refresh() {
    if (lockRef.current) return;
    lockRef.current = true; setBusy(true);
    try { accept(await readResponse(await fetch("/life/api/state", { cache: "no-store" }))); setNotice({ kind: "success", message: "Prehľad je aktuálny." }); }
    catch (error) { setNotice({ kind: "error", message: error instanceof Error ? error.message : "Obnovenie zlyhalo." }); }
    finally { lockRef.current = false; setBusy(false); }
  }
  async function save(command: LifeCommand | LifeCommand[], expectedVersion = versionRef.current): Promise<boolean> {
    if (lockRef.current) return false;
    lockRef.current = true; setBusy(true); setNotice(null);
    try {
      const body = await readResponse(await fetch("/life/api/state", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ expectedVersion, ...(Array.isArray(command) ? { commands: command } : { command }) }) }));
      accept(body); setNotice({ kind: "success", message: "Uložené v tvojom súkromnom priestore." }); return true;
    } catch (error) {
      if (error instanceof Error && "status" in error && error.status === 409) {
        try { accept(await readResponse(await fetch("/life/api/state", { cache: "no-store" }))); } catch { /* Keep the original error visible. */ }
      }
      setNotice({ kind: "error", message: error instanceof Error ? error.message : "Uloženie zlyhalo." }); return false;
    } finally { lockRef.current = false; setBusy(false); }
  }
  async function submitChat(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const message = chatValue.trim(); if (!message || lockRef.current) return;
    lockRef.current = true; setChatBusy(true); setNotice(null);
    try {
      const body = await readResponse(await fetch("/life/api/chat", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ message, history: state.chatMessages.slice(-20).map(item => ({ role: item.role, content: item.content })), expectedVersion: versionRef.current }) }));
      accept(body); setProposalVersion(typeof body.version === "number" ? body.version : null); setChatValue(""); setChatProposals(Array.isArray(body.proposals) ? body.proposals as Proposal[] : []);
      if (body.memorySaved) setNotice({ kind: "success", message: "Pamäť je aktualizovaná. Zmenu nájdeš aj v histórii." });
    } catch (error) { setNotice({ kind: "error", message: error instanceof Error ? error.message : "Asistent momentálne neodpovedá." }); }
    finally { lockRef.current = false; setChatBusy(false); }
  }
  async function parseImport(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (importBusy) return;
    setImportBusy(true); setImportError(""); setImportPreview(null);
    try { const body = await readResponse(await fetch("/life/api/import", { method: "POST", body: new FormData(event.currentTarget) })); setImportPreview(body as ImportPreview); }
    catch (error) { setImportError(error instanceof Error ? error.message : "Import sa nepodarilo spracovať."); }
    finally { setImportBusy(false); }
  }
  const edit = (request: EditorRequest) => { editorVersion.current = versionRef.current; setNotice(null); setEditor(request); };
  const openImport = () => { setImportPreview(null); setImportError(""); setImportOpen(true); };
  const goto = (next: View) => { setView(next); setMobileMenu(false); setNotice(null); };
  const taskToggle = (task: LifeTask) => save({ type: "upsert", collection: "tasks", record: { ...task, done: !task.done } });
  const remove = (collection: LifeCollection, id: string, title: string) => setDeletion({ collection, id, title });
  const allBusy = busy || chatBusy;
  const displayReminders = view === "reminders" ? state.reminders.map(item => ({ item, occurrence: reminderDisplayOccurrence(item, state.settings.timezone) })).sort((a, b) => (a.occurrence?.dueAt || a.item.dueAt || "z").localeCompare(b.occurrence?.dueAt || b.item.dueAt || "z")) : [];
  return <div className="life-app" data-theme={theme}><div className="life-shell">
    <aside className="life-sidebar"><div className="life-brand"><span className="life-brand-mark">si</span><div><strong>SI For Me</strong><small>BY BENDALABS</small></div></div><p className="life-nav-label">TVOJ OSOBNÝ PRIESTOR</p><nav className="life-nav" aria-label="Hlavná navigácia">{navigation.map(item => <button key={item.id} onClick={() => goto(item.id)} aria-current={view === item.id ? "page" : undefined}><item.icon size={17} strokeWidth={1.6} /><span>{item.title}</span>{item.id === "memory" && state.memories.length ? <span className="life-nav-count">{state.memories.filter(memory => memory.active).length}</span> : null}</button>)}</nav><div className="life-sidebar-bottom"><div style={{ padding: "0 9px 20px" }}><p className="life-subtle" style={{ fontSize: 10, display: "flex", alignItems: "center", gap: 6 }}><LockKeyhole size={12} />Súkromný priestor</p></div><div className="life-person"><span className="life-avatar">{visibleName.slice(0, 2).toLocaleUpperCase("sk")}</span><div><strong>{visibleName}</strong><small>Tvoj život. Tvoj systém.</small></div></div></div></aside>
    <main className="life-main"><header className="life-topbar"><div className="life-breadcrumb"><span>Môj priestor</span><ChevronRight size={12} /><span>{navigation.find(item => item.id === view)?.title}</span></div><div className="life-mobile-brand"><span className="life-brand-mark">si</span>SI For Me</div><div className="life-topbar-actions"><span className="life-status"><i />{allBusy ? "Pracujem…" : `Uložené · v${version}`}</span><button title={theme === "dark" ? "Svetlý režim" : "Tmavý režim"} aria-label={theme === "dark" ? "Zapnúť svetlý režim" : "Zapnúť tmavý režim"} className="life-icon-button" onClick={() => storeTheme(theme === "dark" ? "light" : "dark")}>{theme === "dark" ? <Sun size={15} /> : <Moon size={15} />}</button><button title="Obnoviť prehľad" aria-label="Obnoviť prehľad" className="life-icon-button" disabled={allBusy} onClick={refresh}><RefreshCw size={14} /></button><button aria-label="Otvoriť pripomienky" className="life-icon-button" onClick={() => goto("reminders")}><Bell size={15} /></button></div></header>
      {notice ? <div role={notice.kind === "error" ? "alert" : "status"} className={`life-notice life-alert-bar ${notice.kind === "error" ? "life-notice-danger" : "life-notice-success"}`}><span>{notice.message}</span><button aria-label="Zavrieť hlásenie" onClick={() => setNotice(null)}><X size={14} /></button></div> : null}
      {view === "today" ? <Today state={state} today={today} goto={goto} edit={edit} busy={allBusy} taskToggle={taskToggle} /> : null}
      {view === "finance" ? <Finance state={state} version={version} busy={allBusy} edit={edit} save={save} openImport={openImport} /> : null}
      {view === "health" ? <Health state={state} edit={edit} openImport={openImport} /> : null}
      {view === "projects" ? <Projects state={state} edit={edit} busy={allBusy} taskToggle={taskToggle} remove={remove} /> : null}
      {view === "assistant" ? <><div className="life-heading"><div><p className="life-eyebrow">JEDEN ROZHOVOR. CELÝ KONTEXT.</p><h1>Poďme to vyriešiť.</h1><p>Financie, zdravie, tvoje plány aj to, čo si ma už naučil.</p></div><span className={`life-badge ${capabilities.ai ? "life-badge-green" : "life-badge-amber"}`}>{capabilities.ai ? "AI pripravená" : "AI zatiaľ nepripojená"}</span></div><div className="life-chat-layout"><Panel className="life-chat-panel"><div ref={messagesRef} className="life-messages" aria-live="polite">{state.chatMessages.length ? state.chatMessages.map(item => <div className={`life-message ${item.role === "user" ? "life-message-user" : ""}`} key={item.id}><span className="life-message-icon">{item.role === "assistant" ? <Sparkles size={14} /> : "TY"}</span><div className="life-message-body"><strong>{item.role === "assistant" ? "SI For Me" : visibleName} · {new Date(item.createdAt).toLocaleTimeString("sk-SK", { hour: "2-digit", minute: "2-digit", timeZone: state.settings.timezone })}</strong>{item.content}</div></div>) : <Empty title="Čo dnes potrebuješ?" description="Pýtaj sa na svoje údaje, rozober projekt alebo mi povedz, čo si mám zapamätať." />}{chatBusy ? <div className="life-message"><span className="life-message-icon"><Sparkles size={14} /></span><p className="life-subtle"><span className="life-loading-dot" /> Pripravujem odpoveď…</p></div> : null}{chatProposals.map(proposal => <div className="life-notice life-notice-neutral" key={proposal.id}><div style={{ width: "100%" }}><p>{proposal.label}</p><details style={{ margin: "8px 0", fontSize: 10 }}><summary>Pozrieť navrhnutú zmenu</summary><ProposalDetails command={proposal.command} /></details><div className="life-actions"><button className="life-button life-button-primary" disabled={allBusy} onClick={async () => { if (proposalVersion !== versionRef.current) { setNotice({ kind: "error", message: "Údaje sa od návrhu zmenili. Požiadaj asistenta o aktualizovaný návrh, aby neprepísal novšie zmeny." }); return; } if (await save(proposal.command)) { setProposalVersion(versionRef.current); setChatProposals(current => current.filter(item => item.id !== proposal.id)); } }}><Check size={13} />Použiť zmenu</button><button className="life-button life-button-quiet" onClick={() => setChatProposals(current => current.filter(item => item.id !== proposal.id))}>Zahodiť</button></div></div></div>)}</div>{!capabilities.ai ? <div className="life-notice" style={{ marginBottom: 16 }}>Asistent potrebuje pripojený model. Údaje a pamäť môžeš používať aj cez jednotlivé sekcie.</div> : null}<div className="life-chat-suggestions">{["Na čom by som mal dnes pracovať?", "Zhrň moje posledné finančné údaje.", "Čo si o mne pamätáš?"].map(prompt => <button key={prompt} onClick={() => setChatValue(prompt)}>{prompt}</button>)}</div><form className="life-composer" onSubmit={submitChat}><textarea aria-label="Správa pre asistenta" placeholder="Napíš, čo potrebuješ. Alebo čo si mám zapamätať…" value={chatValue} onChange={event => setChatValue(event.target.value)} maxLength={8000} disabled={chatBusy} /><footer><small>Rozhovor a pamäť sa ukladajú súkromne.</small><button className="life-button life-button-primary" type="submit" disabled={!capabilities.ai || allBusy || !chatValue.trim()}><Send size={14} />Odoslať</button></footer></form></Panel><aside className="life-chat-context life-stack"><Panel title="Tvoj kontext"><div className="life-list">{[["Aktívne projekty", state.projects.filter(item => item.status === "active").length], ["Otvorené úlohy", state.tasks.filter(item => !item.done).length], ["Aktívne spomienky", state.memories.filter(item => item.active).length], ["Zdravotné záznamy", state.healthEntries.length]].map(([label, count]) => <div className="life-row" key={label}><div className="life-row-main"><p>{label}</p></div><span className="life-badge">{count}</span></div>)}</div></Panel><Panel title="Pamätám si">{state.memories.filter(item => item.active).slice(0, 3).map(item => <div className="life-row" key={item.id}><div className="life-row-main"><p>{item.title}</p><small>{item.content.slice(0, 110)}{item.content.length > 110 ? "…" : ""}</small></div></div>)}<div style={{ marginTop: 16 }}><TextButton onClick={() => goto("memory")}>Spravovať pamäť</TextButton></div></Panel></aside></div></> : null}
      {view === "memory" ? <><SectionHeading eyebrow="POSTUPNE VIAC TVOJ" title="Pamäť a pravidlá" description="Fakty, preferencie a postupy, ktoré ovplyvňujú ďalšie rozhovory." action={<button className="life-button life-button-primary" onClick={() => edit({ collection: "memories" })}><Plus size={15} />Naučiť niečo nové</button>} />{state.memories.length ? <div className="life-grid">{state.memories.map(memory => <Panel key={memory.id} title={memory.title} action={<span className={`life-badge ${memory.active ? "life-badge-purple" : ""}`}>{memory.active ? "Používa sa" : "Pozastavené"}</span>}><p className="life-memory-content">{memory.content}</p><div className="life-memory-footer"><span className="life-subtle">{scopeLabels[memory.scope]} · verzia {memory.revision}</span><div className="life-actions"><button className="life-icon-button" title="História zmien" aria-label={`História ${memory.title}`} onClick={() => setMemoryHistory(memory)}><History size={14} /></button><button className="life-icon-button" aria-label={`Upraviť ${memory.title}`} onClick={() => edit({ collection: "memories", record: memory })}><Pencil size={14} /></button><button className="life-icon-button" aria-label={`Vymazať ${memory.title}`} onClick={() => remove("memories", memory.id, memory.title)}><Trash2 size={14} /></button></div></div><p className="life-subtle" style={{ marginTop: 10 }}>Zdroj: {memory.source} · {dayLabel(memory.updatedAt)}</p></Panel>)}</div> : <Panel><Empty title="Začnime tým, čo je pre teba dôležité" description="Ulož preferenciu, pravidlo alebo kontext k projektu. Každú zmenu si môžeš prezrieť a vrátiť." action={<button className="life-button" onClick={() => edit({ collection: "memories" })}><Plus size={14} />Pridať prvú spomienku</button>} /></Panel>}</> : null}
      {view === "reminders" ? <><SectionHeading eyebrow="NECH TO NEMUSÍŠ DRŽAŤ V HLAVE" title="Pripomienky" description="Uložené termíny a nastavenia opakovania na jednom mieste." action={<button className="life-button life-button-primary" onClick={() => edit({ collection: "reminders" })}><Plus size={15} />Nová pripomienka</button>} /><div className="life-notice life-notice-neutral" style={{ marginBottom: 20 }}><Bell size={15} /><span>{capabilities.push ? "Upozornenia sú dostupné podľa nastavení tohto zariadenia." : "Pripomienky sa teraz zobrazujú v aplikácii. Doručovanie push správ na pozadí ešte nie je pripojené."}</span></div><Panel title="Tvoje pripomienky">{state.reminders.length ? <div className="life-list">{displayReminders.map(({ item, occurrence }) => <div className="life-row" key={item.id}><span className="life-row-icon"><Bell size={16} /></span><div className="life-row-main"><p>{item.title}</p><small>{item.dueAt ? new Date(occurrence?.dueAt || item.dueAt).toLocaleString("sk-SK", { timeZone: state.settings.timezone, dateStyle: "medium", timeStyle: "short" }) : "Čaká na určenie času"} · {({ none: "jednorazovo", daily: "denne", weekdays: "pracovné dni", weekly: "týždenne", monthly: "mesačne" })[item.repeat]}</small>{item.note ? <small>{item.note}</small> : null}</div><span className={`life-badge ${item.enabled ? "life-badge-purple" : ""}`}>{item.enabled ? occurrence?.status === "overdue" ? "Po termíne" : occurrence?.status === "due" ? "Teraz" : "Naplánovaná" : "Vypnutá"}</span><button className="life-icon-button" aria-label={`Upraviť ${item.title}`} onClick={() => edit({ collection: "reminders", record: item })}><Pencil size={14} /></button><button className="life-icon-button" aria-label={`Vymazať ${item.title}`} onClick={() => remove("reminders", item.id, item.title)}><Trash2 size={14} /></button></div>)}</div> : <Empty title="Prvá pripomienka" description="Zadaj konkrétny čas. Nápad bez termínu môže zostať uložený ako neaktívny." />}</Panel></> : null}
      {view === "documents" ? <><SectionHeading eyebrow="JEDNO MIESTO PRE VŠETKO PODSTATNÉ" title="Podklady a nápady" description="Výpisy, poznámky a kontext, ku ktorému sa vieš vrátiť." action={<div className="life-actions"><button className="life-button" onClick={openImport}><Upload size={14} />Importovať</button><button className="life-button life-button-primary" onClick={() => edit({ collection: "documents" })}><Plus size={15} />Poznámka</button></div>} />{state.documents.length ? <div className="life-grid">{state.documents.map(item => <Panel key={item.id} title={item.title} action={<FileText size={17} color="var(--life-purple)" />}><p className="life-note-body">{item.note.slice(0, 350)}{item.note.length > 350 ? "…" : ""}</p><div className="life-memory-footer"><span className="life-subtle">{dayLabel(item.date)} · {item.source}</span><div className="life-actions"><button className="life-icon-button" aria-label={`Otvoriť ${item.title}`} onClick={() => edit({ collection: "documents", record: item })}><Pencil size={14} /></button><button className="life-icon-button" aria-label={`Vymazať ${item.title}`} onClick={() => remove("documents", item.id, item.title)}><Trash2 size={14} /></button></div></div></Panel>)}</div> : <Panel><Empty title="Daj nápadom miesto" description="Ulož text, poznámku alebo importuj podklad. Priraď ho k projektu a neskôr sa naň opýtaj asistenta." /></Panel>}</> : null}
      {view === "radar" ? <RadarView state={state} edit={edit} save={save} busy={allBusy} version={version} getVersion={() => versionRef.current} ai={capabilities.ai} /> : null}
      {view === "settings" ? <SettingsView state={state} capabilities={capabilities} save={save} busy={allBusy} /> : null}
    </main>
  </div>
  <nav className="life-mobile-nav" aria-label="Mobilná navigácia">{navigation.filter(item => ["today", "finance", "health", "assistant"].includes(item.id)).map(item => <button key={item.id} aria-current={view === item.id ? "page" : undefined} onClick={() => goto(item.id)}><item.icon size={19} strokeWidth={1.6} /><span>{item.title}</span></button>)}<button aria-current={!["today", "finance", "health", "assistant"].includes(view) ? "page" : undefined} onClick={() => setMobileMenu(true)}><MoreHorizontal size={20} /><span>Viac</span></button></nav>
  {mobileMenu ? <Modal title="Tvoj priestor" onClose={() => setMobileMenu(false)}><div className="life-detail life-mobile-menu">{navigation.filter(item => !["today", "finance", "health", "assistant"].includes(item.id)).map(item => <button className="life-button" key={item.id} onClick={() => goto(item.id)}><item.icon size={18} /><span>{item.title}</span><ChevronRight size={15} /></button>)}</div></Modal> : null}
  {editor ? <RecordEditor key={`${editor.collection}-${String(editor.record?.id || "new")}`} request={editor} state={state} busy={allBusy} onSave={command => save(command, editorVersion.current)} onClose={() => setEditor(null)} onRemove={editor.record?.id ? () => { const record = editor.record!; setEditor(null); remove(editor.collection, String(record.id), String(record.title || record.number || record.date || "Záznam")); } : undefined} /> : null}
  {memoryHistory ? <Modal title={`História · ${memoryHistory.title}`} onClose={() => setMemoryHistory(null)}><div className="life-detail">{notice?.kind === "error" ? <p className="life-notice life-notice-danger" role="alert">{notice.message}</p> : null}{[...memoryHistory.history].reverse().map(revision => <div className="life-panel" key={revision.revision}><div className="life-toolbar"><span className="life-badge">Verzia {revision.revision}</span><span className="life-subtle">{dayLabel(revision.changedAt)}</span></div><h3>{revision.title}</h3><p className="life-subtle" style={{ margin: "8px 0 12px" }}>{scopeLabels[revision.scope]} · {revision.active ? "Aktívne" : "Pozastavené"} · {revision.source}</p><p className="life-memory-content">{revision.content}</p>{revision.revision !== memoryHistory.revision ? <button style={{ marginTop: 15 }} className="life-button" disabled={allBusy} onClick={async () => { if (await save({ type: "restore_memory", id: memoryHistory.id, revision: revision.revision })) setMemoryHistory(null); }}><History size={14} />Obnoviť túto verziu</button> : <p className="life-subtle" style={{ marginTop: 12 }}>Aktuálna verzia</p>}</div>)}</div></Modal> : null}
  {deletion ? <Modal title="Vymazať záznam?" onClose={() => setDeletion(null)} busy={allBusy} onSubmit={async event => { event.preventDefault(); if (await save({ type: "remove", collection: deletion.collection, id: deletion.id })) setDeletion(null); }} submitLabel="Vymazať">{notice?.kind === "error" ? <p className="life-notice life-notice-danger" role="alert">{notice.message}</p> : null}<p className="life-note-body">{deletion.title}</p><p className="life-form-note">Záznam sa odstráni zo súkromného priestoru.{deletion.collection === "projects" ? " Súvisiace úlohy a platby zostanú zachované bez priradenia k projektu." : ""}{deletion.collection === "memories" ? " Odstráni sa aj história tejto spomienky." : ""}</p></Modal> : null}
  {importOpen ? <Modal title="Import podkladu" subtitle="Najprv ukážeme rozpoznané údaje. Uložia sa až po tvojej kontrole." busy={importBusy || allBusy} onClose={() => setImportOpen(false)}><div className="life-detail"><form onSubmit={parseImport} className="life-stack"><Field label="Súbor" hint="PDF, CSV, TSV, TXT alebo Markdown · najviac 4 MB"><input name="file" type="file" required accept=".csv,.tsv,.txt,.md,.pdf" disabled={importBusy || allBusy} /></Field><p className="life-subtle">Uloží sa rozpoznaný obsah a evidencia podkladu. Pôvodný súbor si uchovaj; v tejto verzii sa nearchivuje.</p><button className="life-button" disabled={importBusy || allBusy} type="submit"><Upload size={14} />{importBusy ? "Spracúvam podklad…" : "Načítať na kontrolu"}</button></form>{importError ? <p className="life-notice life-notice-danger" role="alert">{importError}</p> : null}{importPreview ? <><div className={`life-notice ${importPreview.duplicate ? "" : "life-notice-neutral"}`}>{importPreview.duplicate ? "Tento podklad už je zaevidovaný. Duplicitný import sa neuloží." : `${importPreview.proposals.length} navrhnutých zmien na kontrolu.`}</div>{importPreview.notes?.map((note, index) => <p key={index} className="life-subtle">{note}</p>)}{importPreview.proposals.map(proposal => <details key={proposal.id} className="life-panel"><summary>{proposal.label}</summary><ProposalDetails command={proposal.command} /></details>)}{!importPreview.duplicate && importPreview.proposals.length ? <button className="life-button life-button-primary" disabled={allBusy} onClick={async () => { if (versionRef.current !== importPreview.version) { setImportError("Údaje sa od načítania náhľadu zmenili. Načítaj súbor znovu, aby sme import porovnali s aktuálnym stavom."); return; } if (await save(importPreview.proposals.map(item => item.command))) setImportOpen(false); else setImportError("Uloženie importu sa nepodarilo potvrdiť. Obnov údaje a načítaj súbor znovu; duplicitný import sa skontroluje."); }}><Check size={14} />Potvrdiť a uložiť celý import</button> : null}</> : null}</div></Modal> : null}
  </div>;
}

function SectionHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="life-heading"><div><p className="life-eyebrow">{eyebrow}</p><h1>{title}</h1><p>{description}</p></div>{action}</div>;
}

function TaskList({ state, tasks, busy, toggle, edit }: { state: LifeState; tasks: LifeTask[]; busy: boolean; toggle: (task: LifeTask) => Promise<boolean>; edit: (request: EditorRequest) => void }) {
  return <div className="life-list">{tasks.map(task => <div className="life-row" key={task.id}><button className="life-check" aria-label={`${task.done ? "Znova otvoriť" : "Dokončiť"} ${task.title}`} aria-pressed={task.done} disabled={busy} onClick={() => toggle(task)}>{task.done ? <Check size={13} /> : null}</button><div className="life-row-main"><p className={task.done ? "life-complete" : ""}>{task.title}</p><small>{task.projectId ? `${state.projects.find(item => item.id === task.projectId)?.title} · ` : ""}{dayLabel(task.dueDate || "")}{task.priority === "high" ? " · vysoká priorita" : ""}</small></div><button className="life-icon-button" aria-label={`Upraviť ${task.title}`} onClick={() => edit({ collection: "tasks", record: task })}><MoreHorizontal size={15} /></button></div>)}</div>;
}

function Today({ state, today, goto, edit, taskToggle, busy }: { state: LifeState; today: string; goto: (view: View) => void; edit: (request: EditorRequest) => void; taskToggle: (task: LifeTask) => Promise<boolean>; busy: boolean }) {
  const tasks = state.tasks.filter(item => !item.done).sort((a, b) => (a.priority === "high" ? -1 : 0) - (b.priority === "high" ? -1 : 0) || (a.dueDate || "z").localeCompare(b.dueDate || "z")).slice(0, 5);
  const finance = summarizeFinances(state, today.slice(0, 7), today);
  const health = [...state.healthEntries].filter(item => item.date <= today).sort((a, b) => b.date.localeCompare(a.date))[0];
  const latestSleep = [...state.healthEntries].filter(item => item.date <= today && item.sleepHours !== null).sort((a, b) => b.date.localeCompare(a.date))[0];
  const projects = state.projects.filter(item => item.status === "active").slice(0, 3);
  const reminders = state.reminders.filter(item => item.enabled && (!item.taskId || !state.tasks.find(task => task.id === item.taskId)?.done)).map(item => ({ item, occurrence: reminderDisplayOccurrence(item, state.settings.timezone) })).filter(entry => entry.occurrence && (entry.occurrence.status !== "upcoming" || new Intl.DateTimeFormat("en-CA", { timeZone: state.settings.timezone, year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date(entry.occurrence.dueAt)) === today)).sort((a, b) => a.occurrence!.dueAt.localeCompare(b.occurrence!.dueAt));
  const greeting = Number(new Intl.DateTimeFormat("en", { timeZone: state.settings.timezone, hour: "numeric", hourCycle: "h23" }).format(new Date())) < 12 ? "Dobré ráno" : "Ahoj";
  return <><SectionHeading eyebrow={new Date(`${today}T12:00:00`).toLocaleDateString("sk-SK", { weekday: "long", day: "numeric", month: "long" })} title={`${greeting}, ${state.settings.displayName}.`} description="Tvoje peniaze, zdravie a plány. Pekne spolu." action={<button className="life-button" onClick={() => edit({ collection: "tasks" })}><Plus size={14} />Pridať úlohu</button>} />
  <div className="life-grid-main" style={{ marginBottom: 22 }}><section className="life-hero"><span className="life-hero-label"><Sparkles size={15} />PRIESTOR NA TO PODSTATNÉ</span><h2>{tasks[0] ? tasks[0].title : "Čomu sa chceš dnes venovať?"}</h2><p>{tasks[0] ? `${tasks[0].priority === "high" ? "Tvoja úloha s vysokou prioritou. " : "Najbližšia otvorená úloha. "}${tasks[0].note || "Rozober ju s asistentom a nájdi najbližší uskutočniteľný krok."}` : "Zachyť myšlienku, nastav si ďalší krok alebo si so mnou prejdi, čo máš rozpracované."}</p><div className="life-actions"><button className="life-button life-button-primary" onClick={() => goto("assistant")}>Prebrať s asistentom<ArrowRight size={14} /></button><button className="life-button life-button-quiet" onClick={() => goto("projects")}>Moje projekty</button></div></section><Panel title="Potrebuje tvoju pozornosť" eyebrow="PREHĽAD"><div className="life-list"><div className="life-row"><span className="life-row-icon"><Wallet size={17} /></span><div className="life-row-main"><p>{finance.basis === "empty" ? "Financie za tento mesiac čakajú na výpis" : finance.pendingCount ? `${finance.pendingCount} platieb na kontrolu` : "Finančné podklady sú na jednom mieste"}</p><small>{finance.basis === "empty" ? "Starší prehľad nájdeš vo Financiách" : finance.monthComplete ? "Mesiac označený ako úplný" : "Úplnosť mesiaca ešte nie je potvrdená"}</small></div><button className="life-icon-button" aria-label="Otvoriť financie" onClick={() => goto("finance")}><ArrowUpRight size={15} /></button></div><div className="life-row"><span className="life-row-icon"><Heart size={17} /></span><div className="life-row-main"><p>{health ? `Posledný zdravotný záznam · ${dayLabel(health.date)}` : "Ako sa dnes cítiš?"}</p><small>{health ? "Pridaj ďalší deň a sleduj vývoj" : "Stačí energia, spánok a krátka poznámka"}</small></div><button className="life-icon-button" aria-label="Pridať zdravotný záznam" onClick={() => edit({ collection: "healthEntries" })}><Plus size={15} /></button></div><div className="life-row"><span className="life-row-icon"><Brain size={17} /></span><div className="life-row-main"><p>{state.memories.filter(item => item.active).length} aktívnych spomienok</p><small>Preferencie a pravidlá pre ďalšie rozhovory</small></div><button className="life-icon-button" aria-label="Otvoriť pamäť" onClick={() => goto("memory")}><ArrowUpRight size={15} /></button></div></div></Panel></div>
  <div className="life-metrics"><Metric label={`Peniaze · ${today.slice(0, 7)}`} value={maybeEur(finance.incomeCents)} note={finance.incomeCents === null ? "Príjmy zatiaľ nepoznáme" : "Zaznamenané príjmy · pozri úplnosť mesiaca"} icon={<Wallet />} /><Metric label="Spánok · posledný záznam" value={latestSleep ? `${latestSleep.sleepHours} h` : "—"} note={latestSleep ? dayLabel(latestSleep.date) : "Zatiaľ bez merania spánku"} icon={<Heart />} /><Metric label="Aktívne projekty" value={state.projects.filter(item => item.status === "active").length} note={`${state.tasks.filter(item => !item.done).length} otvorených úloh`} icon={<FolderOpen />} /></div>
  <div className="life-grid-main"><Panel title="Najbližšie kroky" action={<TextButton onClick={() => goto("projects")}>Všetky úlohy</TextButton>}>{tasks.length ? <TaskList state={state} tasks={tasks} busy={busy} toggle={taskToggle} edit={edit} /> : <Empty title="Daj dňu jeden jasný krok" description="Úloha môže byť malá. Dôležité je vedieť, čo spravíš ako ďalšie." action={<button className="life-button" onClick={() => edit({ collection: "tasks" })}><Plus size={14} />Pridať úlohu</button>} />}</Panel><Panel title="Rozpracované" action={<TextButton onClick={() => goto("projects")}>Projekty</TextButton>}>{projects.length ? <div className="life-list">{projects.map(project => <div className="life-row" key={project.id}><span className="life-row-icon"><FolderOpen size={17} /></span><div className="life-row-main"><p>{project.title}</p><small>{project.nextStep || "Ďalší krok ešte nie je určený"}</small></div></div>)}</div> : <Empty title="Miesto pre tvoje ciele" description="Prepoj ďalší krok, úlohy, termíny aj náklady projektu." />}</Panel></div><Panel title="Pripomienky na dnes" action={<TextButton onClick={() => goto("reminders")}>Všetky termíny</TextButton>} className="life-today-reminders">{reminders.length ? <div className="life-list">{reminders.map(({ item, occurrence }) => <div className="life-row" key={item.id}><span className="life-row-icon"><Bell size={17} /></span><div className="life-row-main"><p>{item.title}</p><small>{new Date(occurrence!.dueAt).toLocaleString("sk-SK", { timeZone: state.settings.timezone, dateStyle: "medium", timeStyle: "short" })}</small></div><span className={`life-badge ${occurrence!.status === "upcoming" ? "life-badge-purple" : "life-badge-amber"}`}>{occurrence!.status === "overdue" ? "Po termíne" : occurrence!.status === "due" ? "Na teraz" : "Dnes"}</span><button aria-label={`Upraviť pripomienku ${item.title}`} className="life-icon-button" onClick={() => edit({ collection: "reminders", record: item })}><Pencil size={14} /></button></div>)}</div> : <p className="life-subtle">Na dnes nemáš žiadnu aktívnu pripomienku ani zmeškaný jednorazový termín.</p>}<p className="life-subtle" style={{ marginTop: 14 }}>Termíny sa vyhodnocujú v aplikácii. Upozornenia na pozadí zatiaľ nie sú pripojené.</p></Panel></>;
}

function Projects({ state, edit, busy, taskToggle, remove }: { state: LifeState; edit: (request: EditorRequest) => void; busy: boolean; taskToggle: (task: LifeTask) => Promise<boolean>; remove: (collection: LifeCollection, id: string, title: string) => void }) {
  const [showDone, setShowDone] = useState(false);
  return <><SectionHeading eyebrow="OD NÁPADU K HOTOVEJ VECI" title="Projekty a ciele" description="Cieľ, ďalší krok a všetky súvisiace úlohy." action={<div className="life-actions"><button className="life-button" onClick={() => edit({ collection: "tasks" })}><Plus size={14} />Úloha</button><button className="life-button life-button-primary" onClick={() => edit({ collection: "projects" })}><Plus size={15} />Projekt</button></div>} /><div className="life-stack">{state.projects.length ? <div className="life-grid">{state.projects.map(project => { const tasks = state.tasks.filter(item => item.projectId === project.id); const complete = tasks.filter(item => item.done).length; const costs = state.transactions.filter(item => item.projectId === project.id && item.confirmed && (item.kind === "expense" || item.kind === "refund")).reduce((sum, item) => sum + item.amountCents * (item.kind === "refund" ? -1 : 1), 0); return <Panel className="life-project-card" key={project.id}><header><span className="life-row-icon"><FolderOpen size={17} /></span><h3>{project.title}</h3><span style={{ marginLeft: "auto" }} className={`life-badge ${project.status === "active" ? "life-badge-purple" : project.status === "completed" ? "life-badge-green" : ""}`}>{({ active: "Aktívny", paused: "Pozastavený", completed: "Hotový" })[project.status]}</span></header><p>{project.description || "Doplň cieľ projektu."}</p><div><p className="life-eyebrow">ĎALŠÍ KROK</p><p style={{ color: "var(--life-fg)" }}>{project.nextStep || "Zatiaľ neurčený"}</p></div><div className="life-project-meta"><span>{complete}/{tasks.length} úloh hotových</span><span>{dayLabel(project.dueDate || "")}</span><span>Náklady: {eur(costs)}{project.budgetCents !== null ? ` / ${eur(project.budgetCents)}` : ""}</span></div><Progress value={complete} max={tasks.length || 1} label={`Postup projektu ${project.title}`} /><footer><button className="life-text-button" onClick={() => edit({ collection: "tasks", record: { projectId: project.id } })}><Plus size={13} />Pridať krok</button><div className="life-actions"><button className="life-icon-button" aria-label={`Upraviť ${project.title}`} onClick={() => edit({ collection: "projects", record: project })}><Pencil size={14} /></button><button className="life-icon-button" aria-label={`Vymazať ${project.title}`} onClick={() => remove("projects", project.id, project.title)}><Trash2 size={14} /></button></div></footer></Panel>; })}</div> : <Panel><Empty title="Na čom chceš pracovať?" description="Pridaj projekt a jeho najbližší krok. Náklady môžeš neskôr priradiť priamo z financií." /></Panel>}<Panel title="Úlohy" action={<label className="life-inline-check"><input type="checkbox" checked={showDone} onChange={event => setShowDone(event.target.checked)} />Aj dokončené</label>}>{state.tasks.filter(item => showDone || !item.done).length ? <TaskList state={state} tasks={state.tasks.filter(item => showDone || !item.done)} busy={busy} toggle={taskToggle} edit={edit} /> : <Empty title="Žiadne otvorené úlohy" description="Pridaj ďalší krok k projektu alebo samostatnú povinnosť." />}</Panel></div></>;
}

type RadarSearchResult = { reply: string; sources: { title: string; url: string }[]; proposals: Proposal[]; version: number };
function RadarView({ state, edit, save, busy, version, getVersion, ai }: { state: LifeState; edit: (request: EditorRequest) => void; save: (command: LifeCommand) => Promise<boolean>; busy: boolean; version: number; getVersion: () => number; ai: boolean }) {
  const [archive, setArchive] = useState(false);
  const [query, setQuery] = useState("");
  const [searchBusy, setSearchBusy] = useState(false);
  const [searchError, setSearchError] = useState("");
  const [result, setResult] = useState<RadarSearchResult | null>(null);
  const items = state.radarItems.filter(item => item.archived === archive);
  async function search(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (searchBusy || !query.trim()) return;
    setSearchBusy(true); setSearchError(""); setResult(null);
    try {
      const body = await readResponse(await fetch("/life/api/radar", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ query: query.trim(), expectedVersion: version }), signal: AbortSignal.timeout(70000) }));
      setResult(body as RadarSearchResult);
    } catch (error) { setSearchError(error instanceof Error ? error.message : "Vyhľadávanie sa nepodarilo dokončiť."); }
    finally { setSearchBusy(false); }
  }
  async function saveResult(proposal: Proposal) {
    if (!result || result.version !== getVersion()) { setSearchError("Tvoje údaje sa medzitým zmenili. Spusť vyhľadávanie znova, aby návrhy pracovali s aktuálnym stavom."); return; }
    if (await save(proposal.command)) setResult(current => current ? { ...current, version: getVersion(), proposals: current.proposals.filter(item => item.id !== proposal.id) } : null);
    else setSearchError("Uloženie sa nepodarilo potvrdiť. Skontroluj hlásenie v aplikácii.");
  }
  return <><SectionHeading eyebrow="ZVEDAVOSŤ, KTORÁ MÁ KAM ÍSŤ" title="Radar" description="Vyhľadaj užitočné zdroje a ulož si to, k čomu sa chceš vrátiť." action={<button className="life-button life-button-primary" onClick={() => edit({ collection: "radarItems" })}><Plus size={15} />Uložiť vlastný odkaz</button>} />
    <Panel title="Čo chceš preskúmať?" className="life-radar-search-panel"><form className="life-radar-search" onSubmit={search}><Field label="Téma alebo otázka"><input value={query} onChange={event => setQuery(event.target.value)} maxLength={1000} required disabled={searchBusy} placeholder="Napr. nové projekty s Raspberry Pi a servo feedbackom" /></Field><button className="life-button life-button-primary" disabled={!ai || searchBusy || busy || !query.trim()} type="submit"><Radar size={15} />{searchBusy ? "Vyhľadávam zdroje…" : "Preskúmať web"}</button></form><p className="life-subtle" style={{ marginTop: 12 }}>{ai ? "Vyhľadávanie sa spustí iba na tvoju žiadosť. Zdroje uložíš až po kontrole." : "Vyhľadávanie potrebuje pripojený AI model. Vlastné odkazy môžeš ukladať hneď."}</p>
      {searchError ? <p className="life-notice life-notice-danger" style={{ marginTop: 18 }} role="alert">{searchError}</p> : null}
      {result ? <div className="life-stack" style={{ marginTop: 24 }}><div className="life-search-answer">{result.reply.split(/(\[\d+\])/g).map((part, index) => { const match = /^\[(\d+)\]$/.exec(part); const source = match ? result.sources[Number(match[1]) - 1] : null; return source ? <a key={index} href={source.url} target="_blank" rel="nofollow noreferrer noopener" aria-label={`Zdroj ${match![1]}: ${source.title}`}>{part}</a> : <span key={index}>{part}</span>; })}</div>{result.sources.length ? <div className="life-list">{result.sources.map((source, index) => <div className="life-row" key={`${source.url}-${index}`}><span className="life-badge">{index + 1}</span><div className="life-row-main"><a href={source.url} target="_blank" rel="nofollow noreferrer noopener">{source.title}</a><small>{new URL(source.url).hostname}</small></div><ArrowUpRight size={14} /></div>)}</div> : <p className="life-subtle">Vyhľadávanie nevrátilo overiteľný zdroj.</p>}{result.proposals.length ? <div className="life-stack">{result.proposals.map(proposal => <div className="life-notice life-notice-neutral" key={proposal.id}><div style={{ width: "100%" }}><p>{proposal.label}</p><details style={{ margin: "9px 0" }}><summary>Pozrieť, čo sa uloží</summary><ProposalDetails command={proposal.command} /></details><button className="life-button" disabled={busy} onClick={() => saveResult(proposal)}><Plus size={13} />Uložiť do radaru</button></div></div>)}</div> : null}</div> : null}
    </Panel>
    <div className="life-toolbar" style={{ marginTop: 24 }}><div className="life-tabs" style={{ marginBottom: 0 }} role="tablist" aria-label="Radar"><button role="tab" aria-selected={!archive} onClick={() => setArchive(false)}>Na prečítanie</button><button role="tab" aria-selected={archive} onClick={() => setArchive(true)}>Archív</button></div><span className="life-subtle">{items.length} uložených zdrojov</span></div>{items.length ? <div className="life-grid">{items.map(item => <Panel title={item.title} key={item.id} action={<span className="life-badge life-badge-purple">{item.topic}</span>}><p className="life-note-body">{item.note}</p>{item.projectId ? <p className="life-subtle" style={{ marginTop: 12 }}>Projekt: {state.projects.find(project => project.id === item.projectId)?.title}</p> : null}<div className="life-memory-footer"><a className="life-button" href={item.url} target="_blank" rel="nofollow noopener noreferrer"><Link2 size={13} />Otvoriť zdroj<ArrowUpRight size={13} /></a><div className="life-actions"><button className="life-icon-button" aria-label={`Upraviť ${item.title}`} onClick={() => edit({ collection: "radarItems", record: item })}><Pencil size={14} /></button><button className="life-button" disabled={busy} onClick={() => save({ type: "upsert", collection: "radarItems", record: { ...item, archived: !item.archived } })}>{item.archived ? "Vrátiť" : "Prečítané"}</button></div></div></Panel>)}</div> : <Panel><Empty title={archive ? "Archív je prázdny" : "Zachyť niečo zaujímavé"} description="Ulož odkaz na výskum, návod alebo inšpiráciu a priraď ho k projektu." /></Panel>}</>;
}

function SettingsView({ state, capabilities, save, busy }: { state: LifeState; capabilities: LifeCapabilities; save: (command: LifeCommand) => Promise<boolean>; busy: boolean }) {
  const [saved, setSaved] = useState(false);
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const data = new FormData(event.currentTarget); setSaved(await save({ type: "settings", patch: { displayName: formString(data, "displayName"), timezone: formString(data, "timezone") } })); }
  return <><SectionHeading eyebrow="PODĽA TEBA" title="Nastavenia" description="Tvoj profil, pripojenia a kontrola nad vlastnými údajmi." /><div className="life-grid"><Panel title="Môj profil"><form onSubmit={submit} className="life-stack"><Field label="Ako ťa mám volať"><input name="displayName" defaultValue={state.settings.displayName} required maxLength={200} /></Field><Field label="Časové pásmo"><select name="timezone" defaultValue={state.settings.timezone}>{[...new Set([state.settings.timezone, "Europe/Paris", "Europe/Bratislava", "Europe/Brussels", "America/Los_Angeles", "Asia/Bangkok", "UTC"])].map(zone => <option key={zone}>{zone}</option>)}</select></Field><div><button className="life-button life-button-primary" disabled={busy} type="submit">Uložiť profil</button>{saved ? <span role="status" className="life-subtle" style={{ marginLeft: 12 }}>Uložené</span> : null}</div></form></Panel><Panel title="Pripojenia"><div className="life-list">{[["AI asistent", capabilities.ai ? "Nakonfigurovaný" : "Čaká na pripojenie modelu"], ["AI model", capabilities.aiModel], ["Uvažovanie", capabilities.aiReasoning], ["Ultrahuman", "Ručné záznamy a import"], ["Banka / iCard", "Import výpisov"], ["Push notifikácie", capabilities.push ? "Dostupné" : "Zatiaľ iba pripomienky v aplikácii"]].map(([label, value]) => <div className="life-row" key={label}><div className="life-row-main"><p>{label}</p><small>{value}</small></div><span className="life-row-icon"><Link2 size={15} /></span></div>)}</div></Panel><Panel title="Súkromie a zariadenia" action={<ShieldCheck size={18} color="var(--life-green)" />}><p className="life-note-body">Prístup chráni prihlásenie. Zapamätané zariadenie používa bezpečnú reláciu; heslo sa neukladá do kódu stránky. Pri vymazaní cookies alebo odhlásení sa prihlásiš znova.</p><div className="life-actions" style={{ marginTop: 20 }}><form action="/life/logout" method="post"><button className="life-button" type="submit"><LogOut size={14} />Odhlásiť zariadenie</button></form><form action="/life/logout" method="post"><input type="hidden" name="all" value="true" /><button className="life-button life-button-quiet" type="submit">Odhlásiť všade</button></form></div></Panel><Panel title="Tvoje dáta patria tebe"><p className="life-note-body">Stiahni si údaje, pamäť a uloženú históriu v jednom JSON súbore. Export obsahuje osobné informácie; ulož ho na súkromné miesto.</p><a className="life-button" href="/life/api/export" style={{ marginTop: 20 }}><ArrowDownToLine size={14} />Stiahnuť export</a><p className="life-subtle" style={{ marginTop: 14 }}>Rozhovor si ponecháva posledných najviac 500 správ v rámci limitu dĺžky. Staršie správy postupne uvoľňujú miesto; výslovne uložená pamäť zostáva samostatne.</p><p className="life-subtle" style={{ marginTop: 14 }}>Posledná zmena: {dayLabel(state.updatedAt)} · verzia údajov {state.version}</p></Panel></div></>;
}

const reviewLabels: Record<string, string> = {
  title: "Názov", content: "Obsah", note: "Poznámka", source: "Zdroj", date: "Dátum", kind: "Typ", category: "Kategória", confirmed: "Skontrolované", amountCents: "Suma", projectId: "Priradený projekt", number: "Číslo faktúry", client: "Odberateľ", issueDate: "Vystavenie", dueDate: "Termín", grossCents: "Celková suma", passThroughCents: "Preúčtované náklady", paidCents: "Zaznamenaná úhrada", status: "Stav", sleepHours: "Spánok (h)", energy: "Energia (1–10)", hrv: "HRV (ms)", restingHr: "Pokojový tep", steps: "Kroky", trainingMinutes: "Tréning (min)", description: "Cieľ", nextStep: "Ďalší krok", budgetCents: "Rozpočet", priority: "Priorita", done: "Dokončené", scope: "Oblasť", active: "Aktívne", dueAt: "Čas", enabled: "Zapnuté", repeat: "Opakovanie", taskId: "Súvisiaca úloha", url: "Odkaz", topic: "Téma", savedDate: "Uložené", archived: "Archivované", month: "Mesiac", asOfDate: "Údaje k dátumu", incomeCents: "Príjmy", refundCents: "Vrátené platby", expenseCents: "Spotreba", debtPrincipalCents: "Splátky istiny", cashWithdrawalCents: "Výbery hotovosti", cashOutflowCents: "Celkové odtoky", invoicedGrossCents: "Fakturácia spolu", invoicedPassThroughCents: "Preúčtované náklady", openingBalanceCents: "Počiatočný zostatok", closingBalanceCents: "Konečný zostatok", categories: "Kategórie", displayName: "Meno", timezone: "Časové pásmo", currency: "Mena", finance: "Finančné nastavenia", expectedMonthlyIncomeCents: "Plánovaný mesačný príjem", monthlyBudgetCents: "Mesačný rozpočet", monthlySavingGoalCents: "Cieľ úspor", reservedCents: "Rezervy", openingBalanceDate: "Dátum počiatočného stavu", dataThroughDate: "Údaje úplné do", reconciled: "Zostatok overený", completeMonths: "Úplné mesiace", categoryLimits: "Limity kategórií", limitCents: "Limit",
};
const reviewValues: Record<string, string> = { income: "Príjem", expense: "Výdavok", refund: "Vrátená platba", internal_transfer: "Vlastný prevod", debt_principal: "Splátka istiny", cash_withdrawal: "Výber hotovosti", general: "Všeobecné", finance: "Financie", health: "Zdravie", projects: "Projekty", active: "Aktívny", paused: "Pozastavený", completed: "Dokončený", normal: "Bežná", high: "Vysoká", low: "Nízka", none: "Jednorazovo", daily: "Denne", weekdays: "Pracovné dni", weekly: "Týždenne", monthly: "Mesačne", unconfirmed: "Úhrada neoverená", issued: "Vystavená", paid: "Uhradená", partially_paid: "Čiastočne uhradená", cancelled: "Zrušená", draft: "Koncept", statement: "Výpis", invoice: "Faktúra", note: "Poznámka", other: "Iné" };
function ProposalDetails({ command }: { command: LifeCommand }) {
  if (command.type === "remove") return <p className="life-subtle" style={{ marginTop: 10 }}>Vymazanie záznamu: {command.id}</p>;
  if (command.type === "restore_memory") return <p className="life-subtle" style={{ marginTop: 10 }}>Obnovenie pamäte na verziu {command.revision}.</p>;
  const entries = command.type === "settings" ? command.patch : command.record;
  function format(key: string, value: unknown): string {
    if (value === null || value === undefined || value === "") return "Neurčené";
    if (typeof value === "boolean") return value ? "Áno" : "Nie";
    if (typeof value === "number") return key.endsWith("Cents") ? eur(value) : String(value);
    if (Array.isArray(value)) return value.map(item => typeof item === "object" && item ? Object.entries(item).map(([nestedKey, nestedValue]) => `${reviewLabels[nestedKey] || nestedKey}: ${format(nestedKey, nestedValue)}`).join(", ") : String(item)).join("; ");
    if (typeof value === "object") return Object.entries(value).map(([nestedKey, nestedValue]) => `${reviewLabels[nestedKey] || nestedKey}: ${format(nestedKey, nestedValue)}`).join("\n");
    return reviewValues[String(value)] || String(value);
  }
  return <dl className="life-review-list">{Object.entries(entries).filter(([key]) => !["id", "history", "revision", "updatedAt"].includes(key)).map(([key, value]) => <div key={key}><dt>{reviewLabels[key] || key}</dt><dd>{format(key, value)}</dd></div>)}</dl>;
}
